// Restore the baseline drawer preview; extend help links to independent copy groups.
var mp={page:0,copy:null,sub:0,saved:false};
function previewPages(){return mp.saved?state.pages:(state.draftPages||[])}
function resetMultiPreview(){mp.page=0;mp.copy=null;mp.sub=0}
function previewStep(i){mp.page=i;mp.copy=null;mp.sub=0;refreshMultiPreview()}
function previewHelp(i){mp.copy=i;mp.sub=0;refreshMultiPreview()}
function previewSub(delta){var p=previewPages()[mp.page],c=p&&p.copies[mp.copy];if(!c||!c.subs.length)return;mp.sub=(mp.sub+delta+c.subs.length)%c.subs.length;refreshMultiPreview()}
function multiPhone(){
 var pages=previewPages();if(!pages.length)return '<div class="pv-empty-hint">当前语言暂无配置</div>';
 mp.page=Math.max(0,Math.min(mp.page,pages.length-1));var p=pages[mp.page];
 var out='<div class="pv-page"><div class="pv-header"><button type="button" class="pv-back" aria-label="预览上一步" '+(!mp.page?'disabled':'')+' onclick="previewStep(mp.page-1)">‹</button><span class="pv-title">Connect to Device</span></div><div class="pv-step-dots">'+pages.map(function(x,i){return '<span class="pv-dot '+(i===mp.page?'active':'')+'"></span>'}).join('')+'</div><div class="pv-page-body"><div class="pv-step-label-inline">Step '+(mp.page+1)+' of '+pages.length+'</div><div class="'+(p.img?'pv-product-img':'pv-product-img-empty')+'">'+(p.img?'▧':'暂无引导图')+'</div><div class="pv-txt">'+esc(p.txt||'请输入配网文案')+'</div>'+(p.auxTxt?'<div class="pv-aux">'+(p.auxSelectable?'☑ ':'')+esc(p.auxTxt)+'</div>':'');
 if(p.guideEnabled)out+=p.copies.map(function(c,i){return '<button type="button" class="pv-guide" onclick="previewHelp('+i+')">'+esc(c.title||'引导文案 '+(i+1))+'</button>'}).join('');
 out+='</div><div class="pv-page-footer"><button type="button" class="pv-action-btn" '+(mp.page===pages.length-1?'disabled':'')+' onclick="previewStep(mp.page+1)">'+esc(p.btnTxt||((mp.saved?state.lang:state.draftLang)==='zh'?'下一步':'Next'))+'</button>'+(mp.page===pages.length-1?'<div class="pv-scanning">Scanning nearby devices…</div>':'')+'</div></div>';
 var c=p.guideEnabled&&mp.copy!==null?p.copies[mp.copy]:null;
 if(c){mp.sub=Math.max(0,Math.min(mp.sub,c.subs.length-1));var sub=c.subs[mp.sub];out+='<div class="pv-modal-overlay"><section class="pv-sheet" aria-label="引导子步骤预览"><div class="pv-sheet-handle"></div><div class="pv-sheet-head"><span class="pv-sheet-title">'+esc(c.title||'引导文案')+'</span><button type="button" class="pv-sheet-close" aria-label="关闭子步骤预览" onclick="mp.copy=null;refreshMultiPreview()">×</button></div><div class="pv-sheet-body">'+(sub?'<div class="pv-substep-full">'+(sub.img?'<div class="pv-substep-full-img">▧</div>':'<div class="pv-substep-full-img-empty">暂无图片</div>')+'<div class="pv-substep-full-body"><div class="pv-substep-full-title">'+esc(sub.title||'请输入子步骤标题')+'</div><div class="pv-substep-full-text">'+esc(sub.body||'请输入子步骤正文')+'</div></div></div>':'暂无子步骤')+'</div><div class="pv-sheet-nav"><button type="button" class="pv-nav-btn" aria-label="上一个子步骤" '+(c.subs.length<=1?'disabled':'')+' onclick="previewSub(-1)">‹</button><span>'+(sub?mp.sub+1:0)+' / '+c.subs.length+'</span><button type="button" class="pv-nav-btn" aria-label="下一个子步骤" '+(c.subs.length<=1?'disabled':'')+' onclick="previewSub(1)">›</button></div></section></div>'}
 return out;
}
function previewPanel(){return '<aside class="multi-preview-col"><div class="preview-label">App 端预览 '+anchor(20)+'</div><div class="phone-mock"><div class="phone-notch"></div><div class="phone-screen" id="multi-phone">'+multiPhone()+'</div></div><p class="form-help">'+(mp.saved?'当前语言已保存内容':'当前语言编辑草稿，尚未保存')+'</p></aside>'}
function refreshMultiPreview(){var node=document.getElementById('multi-phone');if(node)node.innerHTML=multiPhone()}
var originalProvisionDrawer=renderProvisionDrawer;
renderProvisionDrawer=function(){if(state.preview!=='multi')return originalProvisionDrawer();mp.saved=false;return '<div class="drawer-mask" onclick="if(event.target===this)closeDrawer()"><section class="drawer multi-preview-drawer" role="dialog" aria-label="编辑多页面配网引导"><header class="drawer-head"><b class="drawer-title">编辑配网引导 · 多页面配网</b><button type="button" class="close" aria-label="关闭多页面编辑" onclick="closeDrawer()">×</button></header><div class="multi-drawer-body"><div class="multi-form-col">'+renderMultiForm()+'</div>'+previewPanel()+'</div><footer class="drawer-foot"><button class="btn" onclick="closeDrawer()">取消</button><button class="btn btn-primary" onclick="saveProvision()">保存'+anchor(19)+'</button></footer></section></div>'};
var originalMultiForm=renderMultiForm;renderMultiForm=function(){return originalMultiForm().replace(/<header class="step-editor-head">/g,'<header class="step-editor-head">').replace(/<b><span class="step-square">(\d+)<\/span>步骤 (\d+)<\/b>/g,function(all,n){return all+'<button type="button" class="btn btn-sm" onclick="previewStep('+(Number(n)-1)+')">预览步骤 '+n+'</button>'})};
var originalMultiView=renderMultiView;renderMultiView=function(){return '<button type="button" class="btn btn-sm saved-preview-entry" onclick="openSavedPreview()">App 端预览'+anchor(20)+'</button>'+originalMultiView()};
function openSavedPreview(){resetMultiPreview();mp.saved=true;state.modal={kind:'multiPreview'};renderOverlay()}
var originalModal=renderModal;renderModal=function(){if(!state.modal||state.modal.kind!=='multiPreview')return originalModal();return '<div class="modal-mask"><section class="modal multi-preview-modal" role="dialog" aria-label="多页面配网预览"><h3>多页面配网 · App 端预览<button type="button" class="close" style="float:right" aria-label="关闭已保存预览" onclick="state.modal=null;renderOverlay()">×</button></h3>'+previewPanel()+'</section></div>'};
var originalOpenGuide=openDrawer;openDrawer=function(type){if(type==='provision')resetMultiPreview();originalOpenGuide(type)};
var originalDraftLanguage=switchDraftLanguage;switchDraftLanguage=function(lang){resetMultiPreview();originalDraftLanguage(lang)};
document.addEventListener('input',function(e){if(e.target.closest('.multi-form-col'))refreshMultiPreview()});
document.addEventListener('focusin',function(e){var page=e.target.closest('.step-editor');if(page&&state.drawer==='provision'&&state.preview==='multi'&&Number(page.dataset.page)!==mp.page)previewStep(Number(page.dataset.page))});
notes.multiDrawer.items.push([20,'App 端实时预览','关联位置：多页面编辑抽屉右侧','沿用基线手机页面、步骤指示、引导弹层和子步骤翻页。点击预览步骤或编辑对应步骤同步预览；每条引导只打开自己的子步骤，切换引导从第1项开始。实时读取当前语言草稿，取消不影响已保存配置。图片为原型示意，非真实动画播放。']);
notes.provision.items.push([20,'已保存预览','关联位置：多页面查看态 > App端预览','读取当前产品、语言的已保存配置；多个引导各自打开关联子步骤，不混用编辑草稿。新旧接口与旧App消费方案须按PRD兼容清单由技术确认，预览不等同生产兼容已验收。']);
render();
["deleteMultiPage","deleteCopy","deleteSub"].forEach(function(name){var original=window[name];window[name]=function(){mp.copy=null;mp.sub=0;return original.apply(this,arguments)}});
